import althund as H
VID="materials/flight.mp4"
cap=cv2.VideoCapture(VID)
def frame(t):
    cap.set(cv2.CAP_PROP_POS_MSEC,t*1000);ok,f=cap.read()
    return cv2.cvtColor(f,cv2.COLOR_BGR2GRAY).astype(float)

def hundreds_series(t0,t1,dt=1.0):
    ts=np.arange(t0,t1,dt); angs=[]
    for t in ts:
        a=H.peak_angle(H.hundreds_profile(frame(t)))
        angs.append(a if a is not None else np.nan)
    return ts,np.array(angs)

def unwrap_ft(angs):
    # convert angle to hundreds-ft phase, unwrap continuously
    ft=((angs-270)/360*1000)%1000
    out=np.array(ft,float); 
    for i in range(1,len(out)):
        if np.isnan(out[i]): out[i]=out[i-1]; continue
        d=out[i]-out[i-1]
        while d>500: out[i]-=1000; d=out[i]-out[i-1]
        while d<-500: out[i]+=1000; d=out[i]-out[i-1]
    return out

if __name__=='__main__':
    ts,angs=hundreds_series(2,715,3.0)
    ft=unwrap_ft(angs)
    for i in range(0,len(ts),3):
        print(f"t={ts[i]:5.0f} ang={angs[i]:6.1f} rel_ft={ft[i]-ft[0]:+7.0f}")

